@push('styles')<style>
.request-stepper{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem}.request-step{border:0;background:#fff;border-radius:1rem;padding:1rem;box-shadow:0 .35rem 1rem #0c2d5a14;color:#64748b}.request-step span{display:grid;place-items:center;width:2rem;height:2rem;margin:auto;border-radius:50%;background:#e8eef8;font-weight:800}.request-step small{display:block;margin-top:.4rem}.request-step.active{color:#0b5ed7;box-shadow:0 0 0 2px #0b5ed7}.request-step.active span{background:#0b5ed7;color:#fff}.service-choice-card{display:block;position:relative;border:1px solid #dce5f2;border-radius:1rem;padding:1.25rem;background:#fff;cursor:pointer}.service-choice-input{position:absolute;opacity:0}.service-choice-card:has(input:checked){border:2px solid #0b5ed7;background:#f4f8ff}.service-choice-card>strong,.service-choice-card>small{display:block}.service-choice-card>small{color:#64748b}.service-choice-card dl{margin:1rem 0 0}.service-choice-card dl div,.fee-summary-card>div{display:flex;justify-content:space-between;gap:1rem;padding:.35rem 0}.service-choice-card dt{font-weight:500;color:#64748b}.service-choice-card dd{font-weight:700;margin:0}.fee-summary-card{background:#071f43;color:#fff;border-radius:1rem;padding:1.5rem}.fee-summary-card .grand-total{border-top:1px solid #557092;margin-top:.5rem;padding-top:1rem}.fee-summary-card p{color:#c9d7eb;margin:.75rem 0 0}.document-review-list{list-style:none;padding:0}.document-review-list li{display:flex;justify-content:space-between;border-bottom:1px solid #e5eaf1;padding:.65rem 0}.upload-drop-card{display:flex;flex-direction:column;align-items:center;text-align:center;border:2px dashed #8aa8ce;border-radius:1rem;padding:2rem;background:#f8fbff;cursor:pointer}.upload-drop-card i{font-size:2.5rem;color:#0b5ed7}.upload-drop-card input{margin-top:1rem}.review-card{border:1px solid #e1e8f1;border-radius:1rem;padding:1rem;height:100%}.review-card h3{font-size:1rem;color:#0b5ed7}@media(max-width:767px){.request-stepper{grid-temp